    19	
    20	function mapRowToEmployee(row: EmployeeRow): Employee {
    21	  return {
    22	    id: row.id,
    23	    employeeNumber: row.employee_number,
    24	    firstName: row.first_name,
    25	    lastName: row.last_name,
