    33	    updatedAt: row.updated_at,
    34	    deletedAt: row.deleted_at,
    35	  };
    36	}
    37	
    38	const COLUMN_MAP: Record<string, string> = {
    39	  employeeNumber: 'employee_number',
    40	  firstName: 'first_name',
    41	  lastName: 'last_name',
    42	  email: 'email',
    43	  managerId: 'manager_id',
