   104	  async update(id: string, data: Partial<Employee>): Promise<Employee | null> {
   105	    const keys = Object.keys(data).filter(
   106	      (k) =>
   107	        data[k as keyof typeof data] !== undefined &&
   108	        COLUMN_MAP[k] !== undefined,
   109	    );
   110	
   111	    if (keys.length === 0) {
   112	      const existing = await this.findById(id);
   113	      return existing;
   114	    }
   115	
   116	    const setClauses = keys.map(
   117	      (key, index) => `${COLUMN_MAP[key]} = $${index + 2}`,
   118	    );
   119	    const values = keys.map((key) => data[key as keyof typeof data]);
   120	
   121	    const result = await pool.query<EmployeeRow>(
   122	      `UPDATE employees SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id = $1 AND deleted_at IS NULL RETURNING *`,
   123	      [id, ...values],
   124	    );
   125	
   126	    if (result.rows.length === 0) {
   127	      return null;
   128	    }
   129	    return mapRowToEmployee(result.rows[0]);
   130	  }
